package com.indiesoundquest.tournament.domain;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="recording") public class Recording { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="artist_id",nullable=false) private Artist artist; @Column(nullable=false) private String title; @Column(name="album_title") private String albumTitle; @Column(name="version_label") private String versionLabel; @Column(name="seed_rank",nullable=false) private int seedRank; @Column(name="cover_url") private String coverUrl; @Column(name="cover_source") private String coverSource; @Column(name="cover_status") private String coverStatus; protected Recording(){} public UUID getId(){return id;} public String getTitle(){return title;} public Artist getArtist(){return artist;} public String getAlbumTitle(){return albumTitle;} public String getVersionLabel(){return versionLabel;} public String getCoverUrl(){return coverUrl;} public String getCoverStatus(){return coverStatus;} }
